// Generated from shared 1.0.0 content; edit v09-content.js.
namespace DenTinh.Core { public static class RpgCatalog { public static readonly StoryNpc[] Npcs={new StoryNpc{id="elder",name="Bà Năm",position=new V2(10.46875f,46.5625f),portrait=0,chapter=-1,lines=new string[]{"Đêm qua chuông Cội Đa tắt. Mộc Quỷ đã cướp tên của làng. Hãy mở ba Ấn Trúc, Sen, Tro rồi đốt gốc đa để sương không còn đường về. Đốm sẽ dẫn con.","Đừng nghe những lời dưới đầm. Ta đã giữ làng qua mười tám mùa tối. Ba Ấn phải được rút, còn những trang giấy cháy thì cứ để chúng ngủ.","Phải, ta còn nhớ. Ta đã đọc năm cái tên trong đêm hiến tế. Ta sai khi nghĩ giết Cội Đa sẽ xóa được điều chính chúng ta đã làm. Đừng bắt các con quên thêm lần nữa.","Ta sẽ chép lại năm tên trong Sổ Đinh, bằng tay mình. Mỗi năm làng sẽ đọc chúng trước ngọn đèn, không dùng sương để tự tha thứ."}},new StoryNpc{id="smith",name="Chú Bảy",position=new V2(14.53125f,44.0625f),portrait=1,chapter=-1,lines=new string[]{"Búa này rèn được giáp, không rèn được lòng can đảm. I cộng chỉ số, K học chiêu. Nếu muốn tẩy điểm, mang 80 xu về làng.","Sư phụ Hỏa Sơn mất một bàn tay sau đêm rèn ba chiếc đinh. Ta chưa từng dám hỏi vì sao ông giấu khuôn đúc.","Ta từng sửa chiếc đinh thứ hai. Khi ký ức trở lại, ta sẽ nhận phần trách nhiệm ấy, rồi giúp tháo những gì còn trói Cội Đa.","Không còn rèn khóa cho một vòng lặp. Lò này sẽ sửa cầu, đèn và mái nhà."}},new StoryNpc{id="temple_keeper",name="Ông Từ Đạo",position=new V2(10.15625f,48.4375f),portrait=2,chapter=-1,lines=new string[]{"Sổ Đinh thiếu bảy trang, nhưng tro chỉ còn năm khoảng tên. Vết xóa có mùi dầu đèn, không có mùi sương.","Năm tên bị đốt: An, Linh, Quân Lê, HoaVi, Thiên Vũ. Ngày ghi trên mép giấy là mười tám năm trước, không phải đêm qua.","Ta đã giữ bản danh sách hiến tế dưới bàn thờ. Làng đã tự uống nước quên để không phải nghe năm người gọi tên mình.","Sổ mới ghi cả người đã phạm tội lẫn người bị hại. Nhớ đầy đủ mới là thờ phụng."}},new StoryNpc{id="weaver_woman",name="Chị Lụa",position=new V2(6.09375f,46.5625f),portrait=3,chapter=-1,lines=new string[]{"Chiếc nôi trống vẫn có tiếng thở. Con có nghe ngọn đèn gọi một người là cha không?","Ta tìm được đường chỉ trên chiếc tã. Mụ Còng nói nước sen đã rửa ký ức của chính người mẹ đem con mình đi.","An là con ta. Ta nhớ bàn tay mình buông khỏi tay con. Không lời ru nào xóa được điều ấy; ta sẽ ở đây nghe con trả lời.","Hiên nhà còn một ghế. Con không cần tha thứ ngay để được gọi nơi này là nhà."}},new StoryNpc{id="lantern_boy",name="Cậu Bé Tèo",position=new V2(8.75f,41.5625f),portrait=4,chapter=-1,lines=new string[]{"Chong chóng quay ngược dù gió thổi xuôi. Ngoài rừng có tiếng chân giống hệt tiếng chân em.","Em thấy Bà Năm đếm năm bóng trước giếng. Nhưng cả làng bảo đêm ấy không có ai ra khỏi nhà.","Ký ức trở lại làm người lớn khóc. Em sẽ cầm đèn cho họ chép tên, đừng để ai bị bỏ quên nữa.","Lần này tiếng chân ngoài rừng đi cùng chiều với em."}},new StoryNpc{id="blind_bard",name="Lão Mù Ca Trù",position=new V2(29.0625f,52.96875f),portrait=5,chapter=-1,lines=new string[]{"Bảy tiếng trời nằm trong một lồng ngực. Khi nghe tiếng thứ tám, hãy hỏi ai đã khóa tiếng đầu tiên.","Ấn không dẫn đường; đinh đóng đường. Ba nhát búa giam một trái tim đang giữ hộ năm người.","Thiên Vũ, con là phần trời đất thoát khỏi vết đinh. Bảy đài cộng hưởng còn đợi đúng bảy giọng của con.","Đốm mang tiếng tim mà người dệt đã bỏ quên. Một nhịp hy vọng đủ làm khung cửi đổi nhịp."}},new StoryNpc{id="wandering_merchant",name="Lý Gù",position=new V2(32.5f,56.40625f),portrait=6,chapter=-1,lines=new string[]{"Hai lồng đèn này soi hai lối khác nhau. Cổ vật nằm trên bệ hoặc trong tay người canh, đừng mua một lời hứa rỗng.","Ta đổi một mảnh tin: tro dưới đồi còn khuôn đúc ba chiếc đinh. Tìm Hỏa Sơn nếu muốn biết giá của chúng.","Đã có người trả xu để ta im tiếng. Ta giữ tiền như bằng chứng, và sẽ nói điều mình thấy trước đình.","Đường xa còn hàng quán. Giá của sự thật từ nay là chịu nghe hết nó."}},new StoryNpc{id="bamboo_hunter",name="Thợ Săn Già Sơn",position=new V2(16.40625f,65.625f),portrait=7,chapter=-1,lines=new string[]{"Em trai ta đi giữ Ấn Trúc rồi không về. Trúc Vệ mang chiếc mặt nạ em đẽo thuở nhỏ.","Quái vật mang những phần tội lỗi người làng đã cắt khỏi trí nhớ. Ta nhận ra giọng em trong tiếng gầm ấy.","Linh, anh kết nghĩa của con ở sau mặt nạ. Hãy lấy mảnh ký ức dưới bụi trúc; Tịnh Tâm giữ nửa ống tiêu.","Rừng đã yên. Ta sẽ trồng một bụi trúc mang tên em, không gọi em là quái nữa."}},new StoryNpc{id="bamboo_nun",name="Sư Cô Tịnh Tâm",position=new V2(10.625f,70.46875f),portrait=8,chapter=-1,lines=new string[]{"Ngôi mộ gió không chôn thân xác. Ta lần tràng hạt để giữ một giai điệu khỏi tan.","Tám nốt còn trong ống tiêu vỡ: 1, 3, 2, 5, 4, 6, 5, 8. Người thổi phải đem chúng tới bờ Sen.","Linh không bị anh bỏ lại. Anh đã đổi phần người của mình để giữ Linh sống qua đêm hiến tế. Hãy để gió nghe tên anh.","Tiếng tiêu đã hết run. Ta sẽ để bia trống cho người nhà tự chọn lời tiễn."}},new StoryNpc{id="cursed_woodcutter",name="Tiều Phu Hóa Đá",position=new V2(19.375f,71.875f),portrait=9,chapter=-1,lines=new string[]{"Rễ bò lên chân mỗi khi ta cố quên. Nhật ký mắc giữa vỏ cây vẫn còn một trang khô.","Ta nhìn thấy đèn của Bà Năm trước đàn tế. Dân làng đi thành hàng, mỗi người cầm một bát nước sen.","Chân ta hóa rễ vì đã bỏ chạy khi năm người gọi cứu. Cội Đa giữ cả lời thú nhận này.","Rễ đã nới. Ta chưa đi được xa, nhưng sẽ tự bước tới đình để làm chứng."}},new StoryNpc{id="lotus_crone",name="Mụ Còng",position=new V2(44.53125f,49.0625f),portrait=10,chapter=-1,lines=new string[]{"Sen ở đây nở bằng những điều người ta không muốn nhớ. Đừng uống nước trong bát nổi.","Chiếc tã ghi tên An không do sương xóa. Chính làng đã tự uống Nước Đầm Sen Quên Lãng mười tám năm trước.","Ta cũng đã uống. Khi nhớ lại, ta không còn quyền kể mình chỉ là người đứng bên bờ.","Mỗi đóa sen vớt lên sẽ trả về người giữ nó, không đổ xuống nước lần nữa."}},new StoryNpc{id="scholar_ghost",name="Thư Sinh Mặc Khách",position=new V2(50.625f,45f),portrait=11,chapter=-1,lines=new string[]{"Mực vừa chạm giấy đã trôi. Có năm khoảng trống không chịu nhận một tên giả.","Ta tìm được nét cuối của năm tên. Chúng bị lửa đèn đốt đi cùng trang ghi Đêm Thực Nhật.","Cội Đa nuốt lời nguyền để năm linh hồn còn nguyên. Nó không viết bản án; dân làng đã viết.","Ta chép xong rồi. Bản sao này gửi người sống, để người chết không phải giữ sổ mãi."}},new StoryNpc{id="firefly_girl",name="Miên",position=new V2(42.03125f,53.75f),portrait=12,chapter=-1,lines=new string[]{"Đom đóm không dẫn tới vàng. Chúng tìm người có một lời chưa nói.","Những đốm sáng đi từ làng xuống nước, chưa bao giờ đi từ Cội Đa vào làng như lời kể.","Con đom đóm sáng nhất đợi trước hiên Chị Lụa. Nó mang ký ức của An, không mang lời buộc tội.","Đốm đã tìm lại trái tim. Đàn nhỏ của em có thể dẫn những người khác về nhà."}},new StoryNpc{id="ash_forger",name="Lão Hỏa Sơn",position=new V2(45.15625f,67.1875f),portrait=13,chapter=-1,lines=new string[]{"Đừng nhìn bàn tay cụt. Hãy nhìn khuôn đúc. Tro giữ hình dạng đồ vật lâu hơn đầu người.","Ta rèn ba Đinh Phong Ấn theo lệnh làng. Sau đêm ấy ta tự chặt tay vì biết sắt mình rèn đã đóng vào một sinh linh cứu người.","Tro Tàn Của Cha còn cạnh lò cũ. Tâm Đăng của An chứa nửa hồn người cha; nửa còn lại giữ ấm tro suốt mười tám năm.","Ta sẽ dùng bàn tay còn lại rèn bia tên năm người. Không nhận một đồng công nào."}},new StoryNpc{id="ash_gravedigger",name="Kẻ Đào Mộ Tro",position=new V2(50.15625f,70f),portrait=14,chapter=-1,lines=new string[]{"Dưới tro có hai mươi hai dấu giáp. Người chết đứng thành vòng như vẫn chờ lệnh.","Cận Vệ Đêm chết theo chủ, linh hồn hóa hai mươi hai loài bóng thú. Mỗi bia giữ một tên, đừng gộp họ thành một đạo quân vô danh.","Quân Lê, người chủ ấy là con. Khuyên tai thất lạc nằm sau Rừng Gương; đem về đài Tro để gọi đủ tên.","Vĩnh Dạ Thống Soái đã làm điều một thống lĩnh phải làm: nhớ từng người trở về dưới cờ."}},new StoryNpc{id="exiled_pyromancer",name="Pháp Sư Huyền",position=new V2(41.40625f,64.53125f),portrait=15,chapter=-1,lines=new string[]{"Ta bị đuổi khỏi làng vì không chịu nâng bát nước quên. Lửa của ta giữ những trang người khác muốn đốt.","Ta phản đối nghi lễ. Bà Năm nói một làng sống đáng giá hơn năm người; ta không chấp nhận cách đếm ấy.","Thiên Vũ là phần linh hồn đất trời tự tách khỏi Cội Đa khi ba đinh đóng xuống. Hỏa chỉ là một trong bảy giọng.","Lần này người làng được quyền sống cùng ký ức của họ. Ta sẽ trở lại bằng cửa chính."}},new StoryNpc{id="waterfall_hermit",name="Thanh Hư",position=new V2(79.375f,65f),portrait=16,chapter=-1,lines=new string[]{"Lưỡi câu thẳng không bắt cá. Ta đợi một dòng nước chịu kể chuyện mình chảy từ đâu.","Nguồn Thác Ngọc đi qua rễ Cội Đa rồi xuống Đầm Sen. Nó mang ký ức ra ngoài, không nuốt ký ức vào.","Thiên Vũ hãy nghe đủ bảy đài, rồi đối mặt phần bóng tối tại gốc đa. Hợp nhất không phải chém bỏ một nửa mình.","Bảy dòng đã gặp lại. Nước chảy tới ngày mai, không cần một tấm màn giữ mãi hôm qua."}},new StoryNpc{id="windmill_keeper",name="Người Gác Phong",position=new V2(35f,28.59375f),portrait=17,chapter=-1,lines=new string[]{"Cối xay nghiền gió thành tiếng người. Có một lời thề cứ quay trở lại cùng một nhịp.","Ta nghe năm tiếng gọi lặp lại ở mỗi mùa sương. Cỗ máy ở Phế Tích biết vì sao thời gian có đường may.","Khi làng nhận tội, cánh quạt quay thêm một vòng chưa từng có. Phía chân trời còn sáu ngọn đèn.","Không còn lời thề mắc vào trục cối. Gió này có thể thổi tới một miền chưa được dệt sẵn."}},new StoryNpc{id="automaton_07",name="Cơ Linh 07",position=new V2(84.0625f,35.3125f),portrait=18,chapter=-1,lines=new string[]{"Cơ Linh 07. Tín hiệu Bản Thực Thi Số 08 được nhận diện. Quyền đọc Root Log còn thiếu ba mảnh.","HoaVi gốc thiết kế Miền Sương Lạc để giữ ký ức qua tai ương. Bản 08 được gửi vào trong; nhật ký gốc nằm tại Phế Tích và Tháp Sao.","Không cần xóa bản sao để cứu bản gốc. Hợp nhất ba Root Log sẽ cho cả hai quyền sửa Thiên Cơ Tuyến.","Thiên Cơ Mắt Trận đã ghi một lệnh mới: không xóa người kể chỉ vì họ kể khác bản lưu."}},new StoryNpc{id="ferryman",name="Người Lái Đò",position=new V2(112f,54.4375f),portrait=19,chapter=0,lines=new string[]{"Qua bến phải nghe đủ ba tiếng vọng. Đừng gọi người canh trước khi dòng sông kể xong.","Sóng đã mang một chiếc mái chèo này về ba lần. Mỗi lần cùng một vết nứt, khác người cầm.","Ta nhớ những chuyến đò không nằm trong đời mình. Có đường chỉ chạy dưới nước nối về Cội Đa.","Vòng lặp đã mở. Chuyến đò tới bờ mới sẽ không chở lại chính hành khách của hôm qua."}},new StoryNpc{id="mirror_maiden",name="Cô Gái Trong Gương",position=new V2(136f,86.4375f),portrait=20,chapter=1,lines=new string[]{"Gương giữ chín lời kể. Thu ba mảnh trước khi hỏi mặt nào là thật.","Ta đã thấy Quân Lê đứng trước gương cùng chiếc khuyên tai. Bóng thú sau lưng không phải quân bị cưỡng ép.","Có một gương phản chiếu tương lai không còn người trở về. Ai đó đã khâu nó kín bằng sương.","Gương cuối cùng phản chiếu một người biết chọn ngày mai."}},new StoryNpc{id="bell_keeper",name="Người Giữ Miếu Chuông",position=new V2(160f,38.4375f),portrait=21,chapter=2,lines=new string[]{"Chuông không gọi người chết. Nó gọi câu nói bị bỏ dở giữa hai nhịp.","Mỗi vòng chuông lại bắt đầu từ đúng một nốt, dù người đánh đã thay. Hãy nghe tiếng vọng giữa nhịp thứ ba.","Bản đếm trên đồng ghi hàng nghìn vòng. Sương là một đường may thời gian, không còn chỉ là thời tiết.","Chuông hôm nay có thể ngân một tiếng chưa được lưu trước đó."}},new StoryNpc{id="sun_child",name="Đứa Trẻ Nhặt Nắng",position=new V2(184f,6.4375f),portrait=22,chapter=3,lines=new string[]{"Ta gom nắng để trả cho khu vườn. Con rắn giữ nắng vì sợ đêm dài hơn mình.","Một mảnh nắng mang bóng của làng đã cháy, nhưng ngôi làng sau lưng bạn còn nguyên.","Những ngày khác nhau đang chồng vào một tấm vải ký ức. Có người sợ mất làng nên không cho ngày mới đến.","Ta giữ một hạt nắng cho người dệt đã học cách buông tay."}},new StoryNpc{id="bronze_pilot",name="Hoa Tiêu Bằng Đồng",position=new V2(208f,54.4375f),portrait=23,chapter=4,lines=new string[]{"Ba lệnh gốc còn trong tháp. Máy đếm sao chỉ mở đường khi chúng được ghép đủ.","Thiên Cơ ghi tên Memory Tapestry: không gian giữ ký ức, về sau bị sửa thành vòng lặp.","HoaVi đã để một quyền sửa cuối cho Bản 08. Người giữ khung cửi dùng nó để đóng băng thời gian, không phải để cứu mãi một ngôi làng.","Bản gốc và bản 08 cùng giữ quyền viết tiếp. Không còn bộ đếm bắt đầu lại từ không."}},new StoryNpc{id="dom_avatar",name="Hóa Thân Của Đốm",position=new V2(232f,22.4375f),portrait=24,chapter=5,lines=new string[]{"Ta đi cùng bạn từ hiên làng. Trước khi hỏi tên ta, hãy nối những ngọn đèn còn lại.","Ta nhớ đường vì đã chạy dọc đường chỉ rất nhiều lần. Nhưng ta chưa muốn gọi đó là định mệnh.","Mang ba lời đáp tới khung cửi. Người bên trong vẫn còn một phần muốn được ngăn lại.","Ta là trái tim hy vọng Kẻ Dệt Sương tự xé khỏi ngực, gửi ngược về Làng Đèn. Ông là tương lai tuyệt vọng của Người Giữ Đèn Đầu Tiên. Bạn đã cho cả hai một lối đi khác."}}};public static readonly HeroQuestDef[] Quests={new HeroQuestDef{hero="quynhkun",intro="Vết chu sa trên ba chiếc đinh đang phai. Đã đến lúc người cầm bút năm xưa viết nốt chữ cuối cùng.",ending="Mười tám năm trước, Bà Năm ép Quỳnh Kun vẽ Ngũ Đinh Tuyệt Mệnh Phù. Quỳnh Kun cắn máu ngón tay pha chu sa, sửa chữ Tuyệt thành chữ Hộ: Tâm Ấn Hộ Hồn Phù mở đường cho Cội Đa nhận lời nguyền thay năm người. Để giấu bí mật trước phản phệ Thiên Cơ, người cầm bút xé trang thứ sáu của Sổ Đinh, gấp Ẩn Danh Phù và ngủ vùi trong vách đình suốt mười tám năm. Trang thứ bảy thuộc Người Giữ Đèn Đầu Tiên. Nay lá bùa cháy hết, Quỳnh Kun trở lại thu hồi nét bút còn nợ.\n\nNét bút năm xưa không còn phải giấu trong bóng tối. Quỳnh Kun đẩy nhẹ chiếc kính râm trên trán, giữ lại cả tên mình lẫn bình yên của ngôi làng.",reward="Thiên Phù Đại Pháp Sư",steps=new QuestStep[]{new QuestStep{kind="npc",target="temple_keeper",targets=new string[]{},title="Trang Giấy Không Thành Tro",hint="Gặp Ông Từ Đạo tại Đình Làng.",text="Sổ Đinh mất bảy trang mà tro chỉ có năm tên. Ngươi… chính là người thầy cúng đã tự xé trang thứ sáu trong đêm ấy sao?"},new QuestStep{kind="npc",target="scholar_ghost",targets=new string[]{},title="Thứ Mực Không Trôi",hint="Hỏi Thư Sinh Mặc Khách tại Đầm Sen.",text="Dưới bùn Đầm Sen có một nghiên mực đỏ suốt mười tám năm không bị Nước Quên Lãng làm phai chữ."},new QuestStep{kind="memory",target="cinnabar-inkstone",targets=new string[]{},title="Máu Trên Đầu Bút",hint="Tìm Nghiên Chu Sa Nứt tại bờ đông Đầm Sen (3180, 2120).",text=""},new QuestStep{kind="memories",target="",targets=new string[]{"nail-talisman-1","nail-talisman-2","nail-talisman-3"},title="Ba Đạo Phù Tráo Mệnh",hint="Thu hồi ba mảnh Tàn Phù tại Ấn Trúc, Ấn Sen và Ấn Tro.",text=""},new QuestStep{kind="memory",target="sixth-page",targets=new string[]{},title="Lá Bùa Mang Tên Mình",hint="Lấy lại Trang Sổ Đinh Thứ Sáu cất giấu bên hiên Đình Làng (690, 1990).",text=""},new QuestStep{kind="truth",target="",targets=new string[]{},title="Giải Chú Trả Tên",hint="Mở ba Ấn, giải thoát Cội Đa rồi nhấn F trả ký ức cho làng.",text=""},new QuestStep{kind="npc",target="temple_keeper",targets=new string[]{},title="Chữ Ký Của Thầy Phù Thủy",hint="Trở lại báo cho Ông Từ Đạo.",text="Trang thứ sáu đã về lại Sổ Đinh. Làng Đèn từ nay sẽ nhớ người đã lén cứu năm sinh mạng đêm ấy."}}},new HeroQuestDef{hero="an",intro="Ngọn Tâm Đăng gọi An về phía khung cửi của Chị Lụa.",ending="An thắp lại hiên nhà và gọi Chị Lụa là mẹ.\n\nTâm Đăng không còn cháy để giấu nỗi đau. An chọn giữ cả ký ức về cha lẫn người mẹ đã có lỗi.",reward="Tâm Đăng · Nửa Hồn Người Cha",steps=new QuestStep[]{new QuestStep{kind="npc",target="weaver_woman",targets=new string[]{},title="Tiếng Ru Bên Hiên",hint="Gặp Chị Lụa tại hiên phía tây Làng Đèn.",text="Nhịp đèn của con giống tay người từng ngồi bên khung cửi này. Hãy hỏi Hỏa Sơn về tro không nguội."},new QuestStep{kind="npc",target="ash_forger",targets=new string[]{},title="Lò Tro Không Nguội",hint="Tìm Lão Hỏa Sơn ở Đồi Tro.",text="Cha con để lại nửa linh hồn trong Tâm Đăng. Tro ở lò phía đông giữ nửa lời nhắn cuối."},new QuestStep{kind="memory",target="father-ash",targets=new string[]{},title="Tro Tàn Của Cha",hint="Lấy tro ký ức cạnh lò cũ tại 3020, 835.",text=""},new QuestStep{kind="npc",target="weaver_woman",targets=new string[]{},title="Tên Người Mẹ",hint="Mang Tro Tàn về Chị Lụa.",text="An… con là đứa trẻ ta đã đem tới gốc đa. Con được quyền giận. Ta xin nghe hết điều con nhớ."},new QuestStep{kind="truth",target="",targets=new string[]{},title="Đèn Không Đốt Rễ",hint="Mở ba Ấn, giải thoát Mộc Quỷ rồi F tại Cội Đa để trả ký ức.",text=""}}},new HeroQuestDef{hero="linh",intro="Tiếng tiêu trúc gọi Linh từ khu rừng bị phong ấn.",ending="Tám nhịp trúc đưa người anh kết nghĩa về cùng gió.\n\nNgười anh được gọi tên trong gió. Linh giữ ống tiêu đã ghép, tiếp tục bắn cung bằng đôi tay không còn run.",reward="Khúc Tiêu · Trúc Ảnh Trở Về",steps=new QuestStep[]{new QuestStep{kind="npc",target="bamboo_hunter",targets=new string[]{},title="Giọng Sau Mặt Nạ",hint="Gặp Thợ Săn Sơn trong Rừng Trúc.",text="Trúc Vệ còn giữ phần ký ức về người em. Hãy hạ oán khí của nó rồi nhìn sau mặt nạ."},new QuestStep{kind="kill",target="Trúc Vệ",targets=new string[]{},title="Người Anh Trong Trúc",hint="Hoàn thành cuộc săn Trúc Vệ tại Ấn Trúc.",text=""},new QuestStep{kind="memory",target="brother-mask",targets=new string[]{},title="Nút Thắt Cũ",hint="Tìm mảnh mặt nạ tại 925, 790.",text=""},new QuestStep{kind="npc",target="bamboo_nun",targets=new string[]{},title="Tám Nốt Chưa Dứt",hint="Đem mặt nạ tới Sư Cô Tịnh Tâm.",text="Ống tiêu nằm cạnh mộ gió. Đem nó xuống Sen; tám nốt là lời anh chưa kịp nói."},new QuestStep{kind="memory",target="broken-flute",targets=new string[]{},title="Ống Tiêu Trúc Vỡ",hint="Nhặt nửa ống tiêu cạnh mộ gió.",text=""},new QuestStep{kind="notes",target="",targets=new string[]{},title="Khúc Tiễn Tại Bờ Sen",hint="F tại 3100, 2185. Chơi 1 · 3 · 2 · 5 · 4 · 6 · 5 · 8.",text=""},new QuestStep{kind="npc",target="bamboo_nun",targets=new string[]{},title="Tên Trên Bia Gió",hint="Trở về báo Tịnh Tâm sau khúc tiêu.",text="Ta nghe rồi. Anh con không còn bị gọi bằng tên quái vật."}}},new HeroQuestDef{hero="quanle",intro="Hai mươi hai cái bóng vẫn chờ vị thống lĩnh gọi tên.",ending="Quân Lê trở thành Vĩnh Dạ Thống Soái.\n\nHai mươi hai cận vệ đáp lời bằng tên mình. Binh đoàn bước tiếp vì lời thề còn được chọn, không vì xiềng xích.",reward="Vĩnh Dạ Thống Soái",steps=new QuestStep[]{new QuestStep{kind="npc",target="ash_gravedigger",targets=new string[]{},title="Hai Mươi Hai Lời Thề",hint="Gặp Kẻ Đào Mộ Tro.",text="Tìm đủ hai mươi hai bia linh hồn tại Rừng Trúc, Đồi Tro và Thung Lũng Đèn."},new QuestStep{kind="memories",target="",targets=new string[]{"guard-memory-0","guard-memory-1","guard-memory-2","guard-memory-3","guard-memory-4","guard-memory-5","guard-memory-6","guard-memory-7","guard-memory-8","guard-memory-9","guard-memory-10","guard-memory-11","guard-memory-12","guard-memory-13","guard-memory-14","guard-memory-15","guard-memory-16","guard-memory-17","guard-memory-18","guard-memory-19","guard-memory-20","guard-memory-21"},title="Gọi Tên Cận Vệ Đêm",hint="Nhặt ký ức tại 22 bia. M hiển thị bia kế tiếp; I ghi số đã tìm.",text=""},new QuestStep{kind="memory",target="night-earring",targets=new string[]{},title="Khuyên Tai Rừng Gương",hint="Sau Cội Đa, theo chương Biên Viễn tới Rừng Gương, 8845, −440.",text=""},new QuestStep{kind="memory",target="night-memorial",targets=new string[]{},title="Lễ Tưởng Niệm Đồi Tro",hint="Đem khuyên về đài tưởng niệm tại 3060, 1030.",text=""},new QuestStep{kind="npc",target="ash_gravedigger",targets=new string[]{},title="Dưới Cờ Vĩnh Dạ",hint="Trở lại người giữ mộ để hoàn tất lễ.",text="Đủ tên rồi, thống lĩnh. Lần này hãy dẫn họ đến ngày mai."}}},new HeroQuestDef{hero="hoavi",intro="Một bản ghi gọi HoaVi là Bản Thực Thi Số 08.",ending="Bản gốc và bản sao cùng viết lại Thiên Cơ Tuyến.\n\nHoaVi gốc và Bản 08 cùng tồn tại trong một dòng ký ức có hai giọng kể. Mắt Trận nhận lệnh giữ người, không giữ vòng lặp.",reward="Thiên Cơ Mắt Trận",steps=new QuestStep[]{new QuestStep{kind="npc",target="automaton_07",targets=new string[]{},title="Tín Hiệu Số 08",hint="Gặp Cơ Linh 07 tại Phế Tích.",text="Ba Root Log mở quyền hợp nhất. Một ở kho phía nam, một tại Tháp Sao, một trong phòng khóa phía đông."},new QuestStep{kind="memories",target="",targets=new string[]{"root-1","root-2","root-3"},title="Ba Bảng Mã Gốc",hint="Thu ba Root Log ở Phế Tích và Tháp Đếm Sao thuộc chương Biên Viễn thứ năm.",text=""},new QuestStep{kind="npc",target="automaton_07",targets=new string[]{},title="Bản Gốc Và Bản Sao",hint="Mang ba Root Log trở lại Cơ Linh 07.",text="Khóa đã ghép. HoaVi chọn giữ cả bản gốc lẫn Bản 08; không xóa ký ức của ai để hoàn tất hợp nhất."},new QuestStep{kind="truth",target="",targets=new string[]{},title="Sửa Lại Thiên Cơ Tuyến",hint="Giải thoát Cội Đa và trả ký ức cho làng trước khi ghi lệnh mới.",text=""}}},new HeroQuestDef{hero="thienvu",intro="Bảy nguyên tố là bảy mảnh tim của Cội Đa.",ending="Thiên Vũ hợp nhất linh hồn thế giới.\n\nNửa bóng tối không bị xóa; nó nhận lại tên của mình. Thiên Vũ trở thành trái tim biết chịu đau và vẫn chọn giữ thế giới sống.",reward="Thất Linh Chân Thể",steps=new QuestStep[]{new QuestStep{kind="npc",target="blind_bard",targets=new string[]{},title="Tiếng Thứ Tám",hint="Gặp Lão Mù Ca Trù ở Đường Gió.",text="Hỏi Huyền về ngọn lửa còn nhớ vết đinh; Thanh Hư sẽ chỉ dòng nước đưa con về gốc."},new QuestStep{kind="npc",target="exiled_pyromancer",targets=new string[]{},title="Ngọn Lửa Của Trời Đất",hint="Gặp Pháp Sư Huyền ở Đồi Tro.",text="Con không sinh từ nghi lễ của làng. Con là linh hồn tự tách khỏi Cội Đa để sống qua nó."},new QuestStep{kind="npc",target="waterfall_hermit",targets=new string[]{},title="Bảy Dòng Cùng Nguồn",hint="Gặp Thanh Hư tại Thác Ngọc.",text="Dùng đúng dạng nguyên tố tại từng đài. Khi đủ bảy, trở về gốc đa đối mặt phần bóng tối."},new QuestStep{kind="memories",target="",targets=new string[]{"element-altar-lightning","element-altar-wind","element-altar-earth","element-altar-fire","element-altar-ice","element-altar-nature","element-altar-light"},title="Bảy Đài Cộng Hưởng",hint="Thức tỉnh bảy đài bằng đúng dạng 1–7; M chỉ đài kế tiếp.",text=""},new QuestStep{kind="truth",target="",targets=new string[]{},title="Trái Tim Dưới Ba Đinh",hint="Giải thoát Mộc Quỷ, rồi F tại Cội Đa trả ký ức.",text=""},new QuestStep{kind="duel",target="",targets=new string[]{},title="Nửa Bóng Tối Của Chính Mình",hint="F tại 1830, 760 để đối mặt và hợp nhất nửa linh hồn còn lại.",text=""},new QuestStep{kind="npc",target="waterfall_hermit",targets=new string[]{},title="Thất Linh Hợp Nhất",hint="Trở lại Thanh Hư sau trận chiến.",text="Ta thấy bảy dòng đã thôi chống nhau. Từ nay con tự chọn điều trái tim mình giữ."}}}};public static readonly HeroMemory[] Memories={new HeroMemory{id="father-ash",hero="an",name="Tro Tàn Của Cha",text="Tro còn một vệt sáng mang nhịp Tâm Đăng. Giọng người cha: “Nếu con còn sống, hãy đem phần ấm này về với mẹ.”",element="",position=new V2(47.1875f,66.953125f)},new HeroMemory{id="brother-mask",hero="linh",name="Mặt Nạ Trúc Vệ",text="Dưới lớp gỗ có nút thắt Linh từng buộc cho anh. Anh đã đổi thân mình để che Linh qua Đêm Thực Nhật.",element="",position=new V2(14.453125f,67.65625f)},new HeroMemory{id="broken-flute",hero="linh",name="Ống Tiêu Trúc Vỡ",text="Nửa ống còn tám dấu bấm: 1 · 3 · 2 · 5 · 4 · 6 · 5 · 8. Hãy thổi ở bờ Sen khi nước yên.",element="",position=new V2(11.71875f,71.09375f)},new HeroMemory{id="night-earring",hero="quanle",name="Khuyên Tai Cận Vệ Đêm",text="Chiếc khuyên mang đủ hai mươi hai dấu khắc. Quân Lê nhớ rằng họ tự chọn ở lại với mình.",element="",position=new V2(138.203125f,86.875f)},new HeroMemory{id="night-memorial",hero="quanle",name="Đài Tưởng Niệm Đồi Tro",text="Hai mươi hai cái tên được gọi trước cờ. Không còn ai chỉ là một chiếc bóng không tên.",element="",position=new V2(47.8125f,63.90625f)},new HeroMemory{id="root-1",hero="hoavi",name="Root Log 01 · Người Thiết Kế",text="HoaVi gốc: “Miền Sương giữ ký ức người mất nhà. Không được khóa họ vào một ngày duy nhất.”",element="",position=new V2(82.96875f,34.0625f)},new HeroMemory{id="root-2",hero="hoavi",name="Root Log 02 · Bản 08",text="Bản Thực Thi Số 08 mang tư cách một người, không phải tệp dự phòng có thể xóa.",element="",position=new V2(209.6875f,54.375f)},new HeroMemory{id="root-3",hero="hoavi",name="Root Log 03 · Quyền Hợp Nhất",text="Hai khóa gốc và 08 có thể cùng mở Thiên Cơ Tuyến. Hợp nhất giữ cả hai dòng ký ức.",element="",position=new V2(89.0625f,38.125f)},new HeroMemory{id="guard-memory-0",hero="quanle",name="Cận Vệ Dạ Hổ",text="Dạ Hổ: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(17.03125f,62.5f)},new HeroMemory{id="guard-memory-1",hero="quanle",name="Cận Vệ Huyền Lang",text="Huyền Lang: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(42.65625f,62.5f)},new HeroMemory{id="guard-memory-2",hero="quanle",name="Cận Vệ Mặc Hạc",text="Mặc Hạc: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(35.46875f,31.25f)},new HeroMemory{id="guard-memory-3",hero="quanle",name="Cận Vệ Ám Xà",text="Ám Xà: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(17.890625f,62.5f)},new HeroMemory{id="guard-memory-4",hero="quanle",name="Cận Vệ Ô Nha",text="Ô Nha: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(43.515625f,62.5f)},new HeroMemory{id="guard-memory-5",hero="quanle",name="Cận Vệ Thiết Giáp",text="Thiết Giáp: “Chúng ta đã chọn giữ đèn đến hơi thở cuối. Xin thống lĩnh nhớ tên, đừng chỉ nhớ sức mạnh.”",element="",position=new V2(36.328125f,31.25f)},new HeroMemory{id="guard-memory-6",hero="quanle",name="Cận Vệ Huyết Lộ