new HeroMemory{id="element-altar-earth",hero="thienvu",name="Đài Cộng Hưởng Thổ",text="Một mảnh linh hồn đất trời trở về lồng ngực Thiên Vũ. Bảy mảnh không phải bảy người xa lạ.",element="earth",position=new V2(85.15625f,36.25f)},new HeroMemory{id="element-altar-fire",hero="thienvu",name="Đài Cộng Hưởng Hỏa",text="Một mảnh linh hồn đất trời trở về lồng ngực Thiên Vũ. Bảy mảnh không phải bảy người xa lạ.",element="fire",position=new V2(45.3125f,62.1875f)},new HeroMemory{id="element-altar-ice",hero="thienvu",name="Đài Cộng Hưởng Băng",text="Một mảnh linh hồn đất trời trở về lồng ngực Thiên Vũ. Bảy mảnh không phải bảy người xa lạ.",element="ice",position=new V2(77.1875f,66.09375f)},new HeroMemory{id="element-altar-nature",hero="thienvu",name="Đài Cộng Hưởng Mộc",text="Một mảnh linh hồn đất trời trở về lồng ngực Thiên Vũ. Bảy mảnh không phải bảy người xa lạ.",element="nature",position=new V2(18.4375f,66.875f)},new HeroMemory{id="element-altar-light",hero="thienvu",name="Đài Cộng Hưởng Quang",text="Một mảnh linh hồn đất trời trở về lồng ngực Thiên Vũ. Bảy mảnh không phải bảy người xa lạ.",element="light",position=new V2(28.59375f,65.3125f)},new HeroMemory{id="cinnabar-inkstone",hero="quynhkun",name="Nghiên Chu Sa Nứt",text="Dưới đáy nghiên còn vết máu khô hòa cùng chu sa. Đêm Thực Nhật, Quỳnh Kun đã sửa chữ Tuyệt thành chữ Hộ để giữ lại năm linh hồn.",element="",position=new V2(49.6875f,46.875f)},new HeroMemory{id="nail-talisman-1",hero="quynhkun",name="Tàn Phù Ấn Trúc",text="Mảnh bùa thứ nhất trấn trên đinh sắt. Nét bút bị cố tình vẽ lệch một phân để linh hồn người hiến tế có khe thở.",element="",position=new V2(13.4375f,68.4375f)},new HeroMemory{id="nail-talisman-2",hero="quynhkun",name="Tàn Phù Ấn Sen",text="Mảnh bùa thứ hai thấm nước sen nhưng chữ máu không trôi. Cội Đa đã nhận ra thiện ý của người vẽ bùa.",element="",position=new V2(47.8125f,47.96875f)},new HeroMemory{id="nail-talisman-3",hero="quynhkun",name="Tàn Phù Ấn Tro",text="Mảnh bùa thứ ba cháy sém bên lò rèn. Phản phệ đêm ấy đã xóa tên người thầy cúng khỏi ký ức cả làng.",element="",position=new V2(47.65625f,68.59375f)},new HeroMemory{id="sixth-page",hero="quynhkun",name="Trang Sổ Đinh Thứ Sáu",text="Trang giấy gấp thành hình lá bùa cất dưới gạch đình làng, ghi rõ cái tên thứ sáu chưa từng hóa tro: Quỳnh Kun.",element="",position=new V2(10.78125f,48.90625f)}};public static readonly SagaChapter[] Chapters={new SagaChapter{id="river",name="Bến Nước Không Tên",boss="Hà Bá · Người Đòi Lại Dòng Sông",relic="thuytinh",intro="Mộc Quỷ chỉ giữ cánh cửa đầu tiên. Sương đã cuốn tên những con sông vào sáu ngọn đèn lạc. Hãy nghe ba tiếng vọng ở bến nước rồi gọi người canh dòng lên đối thoại.",win="Người canh trả lại ký ức thứ 1. Một đường chỉ ký ức chạy dưới lòng sông về phía khung cửi. Hãy nối ngọn đèn để tiếp tục.",echoes=new string[]{"Chiếc mái chèo mang cùng một vết nứt qua ba cuộc đời.","Dòng nước giữ bóng Làng Đèn đã cháy, rồi bóng làng còn nguyên.","Một đường chỉ ký ức chạy dưới lòng sông về phía khung cửi."},position=new V2(112f,56f)},new SagaChapter{id="fox",name="Rừng Gương Hồ Tinh",boss="Hồ Tinh · Chín Bóng Một Lời Thề",relic="thachsan",intro="Chín chiếc bóng kể chín phiên bản của cùng một lời hứa. Đừng tin bóng đầu tiên. Thu ba mảnh ký ức để biết ai đã tự nguyện ở lại khu rừng.",win="Người canh trả lại ký ức thứ 2. Gương thứ ba có chiếc khuyên tai của Quân Lê; lời thề cận vệ còn nguyên. Hãy nối ngọn đèn để tiếp tục.",echoes=new string[]{"Gương thứ nhất phản chiếu năm người trẻ trước đàn tế.","Gương thứ hai phản chiếu làng đã chết trong một ngày khác.","Gương thứ ba có chiếc khuyên tai của Quân Lê; lời thề cận vệ còn nguyên."},position=new V2(136f,88f)},new SagaChapter{id="bell",name="Miếu Chuông Quên Giờ",boss="Thần Trùng · Kẻ Gõ Giờ Lạc",relic="ankh",intro="Chiếc chuông không gọi người chết. Nó gọi những lời chưa kịp nói. Hãy nhặt ba tiếng vọng quanh miếu để chuông tìm lại nhịp của mình.",win="Người canh trả lại ký ức thứ 3. Người gác nhớ một người giữ đèn đã quay lại hàng nghìn lần. Hãy nối ngọn đèn để tiếp tục.",echoes=new string[]{"Trên chuông khắc số vòng lặp, không phải số năm.","Mỗi nhịp lặp bắt đầu ngay trước Đêm Thực Nhật.","Người gác nhớ một người giữ đèn đã quay lại hàng nghìn lần."},position=new V2(160f,40f)},new SagaChapter{id="serpent",name="Khe Chín Dòng",boss="Cửu Khúc Xà · Kẻ Nuốt Nhật Quang",relic="sontinh",intro="Con rắn uống ánh mặt trời vì tin rằng đêm dài sẽ che được vết thương của thung lũng. Thu ba mảnh nắng, rồi chỉ cho nó thấy nơi bóng tối nên kết thúc.",win="Người canh trả lại ký ức thứ 4. Giữ một ký ức không cho nó thay đổi cũng có thể làm nó chết. Hãy nối ngọn đèn để tiếp tục.",echoes=new string[]{"Nắng rơi trên những ngày khác nhau chồng vào một thung lũng.","Người giữ ngày cũ sợ rằng một ngày mới sẽ lại giết ngôi làng.","Giữ một ký ức không cho nó thay đổi cũng có thể làm nó chết."},position=new V2(184f,8f)},new SagaChapter{id="machine",name="Tháp Đếm Những Vì Sao",boss="Thiết Điểu · Lõi Đồng Câm",relic="hermes",intro="Cỗ máy được tạo để nhớ đường về nhà. Sương khiến nó chỉ nhớ những con số. Hãy gom ba lệnh còn nguyên trước khi đánh thức trái tim đồng.",win="Người canh trả lại ký ức thứ 5. Tọa độ cuối cùng thuộc Người Giữ Đèn Đầu Tiên. Đốm luôn biết đường về đây. Hãy nối ngọn đèn để tiếp tục.",echoes=new string[]{"Root Log gọi thế giới là Memory Tapestry, do HoaVi thiết kế để lưu giữ ký ức.","Một quyền sửa đã biến kho ký ức thành vòng thời gian. Bản 08 được gửi vào để tìm nó.","Tọa độ cuối cùng thuộc Người Giữ Đèn Đầu Tiên. Đốm luôn biết đường về đây."},position=new V2(208f,56f)},new SagaChapter{id="weaver",name="Khung Cửi Bên Kia Chân Trời",boss="Kẻ Dệt Sương · Người Không Còn Tên",relic="ariadne",intro="Đốm dẫn bạn tới một khung cửi đã vá quá nhiều lần. Mang ba lời đáp đến người bên trong. Danh tính của ông chỉ mở khi tấm sương cuối được tháo.",win="Kẻ Dệt Sương tháo mặt nạ: ông là tương lai tuyệt vọng của Người Giữ Đèn Đầu Tiên. Sau hàng nghìn lần nhìn làng bị hủy, ông đóng băng thời gian bằng sương. Đốm sáng lên ở vết trống trong ngực ông: đó là trái tim hy vọng ông tự xé ra và gửi ngược về dẫn bạn đánh bại chính mình. Lần này, ông buông khung cửi. Ngày mai không còn được dệt sẵn.",echoes=new string[]{"Lời đáp của làng: chúng tôi nhận lại tội lỗi, không xin được quên.","Lời đáp của năm người: chúng tôi có quyền sống tiếp sau điều đã xảy ra.","Đốm đặt chân lên đường chỉ cuối: người dệt vẫn còn một phần muốn được ngăn lại."},position=new V2(232f,24f)}};public static WorldRelic[] Pedestals(){return new WorldRelic[]{new WorldRelic{relic="chudong",position=new V2(60.46875f,52.65625f),puzzle="fire",guardCount=2},new WorldRelic{relic="tam",position=new V2(36.09375f,62.03125f),puzzle="",guardCount=0},new WorldRelic{relic="antiem",position=new V2(94.21875f,61.09375f),puzzle="",guardCount=0},new WorldRelic{relic="traucau",position=new V2(6.09375f,22.65625f),puzzle="",guardCount=0},new WorldRelic{relic="aegis",position=new V2(99.84375f,21.71875f),puzzle="",guardCount=2},new WorldRelic{relic="aladdin",position=new V2(81.09375f,73.28125f),puzzle="lightning",guardCount=0},new WorldRelic{relic="jack",position=new V2(20.15625f,77.96875f),puzzle="",guardCount=2},new WorldRelic{relic="cinderella",position=new V2(97.96875f,77.96875f),puzzle="earth",guardCount=0},new WorldRelic{relic="power",position=new V2(65.15625f,78.90625f),puzzle="",guardCount=2},new WorldRelic{relic="vitality",position=new V2(27.65625f,46.09375f),puzzle="",guardCount=0},new WorldRelic{relic="haste",position=new V2(36.09375f,84.53125f),puzzle="",guardCount=2},new WorldRelic{relic="spirit",position=new V2(38.90625f,31.09375f),puzzle="lightning",guardCount=0},new WorldRelic{relic="wildfire",position=new V2(0.46875f,57.34375f),puzzle="",guardCount=0},new WorldRelic{relic="dashshock",position=new V2(44.53125f,47.03125f),puzzle="",guardCount=0},new WorldRelic{relic="split",position=new V2(3.28125f,75.15625f),puzzle="",guardCount=2},new WorldRelic{relic="pierce",position=new V2(52.96875f,15.15625f),puzzle="",g